/** RF-014 a RF-020: una foto y una conversación, con los campos y motor actuales. */
final class ConversacionEvaluacion {
 private ConversacionEvaluacion(){}
 static String nueva(Sesion s,Evaluaciones.Contexto c,int id){return pagina(s,c.puestos(),id,c.visita().visita().id(),c.visita().empresaNombre()+" · "+c.visita().salonNombre());}
 private static String pagina(Sesion s,List<Puesto> puestos,int id,int visita,String lugar){
  var p=puestos.stream().filter(x->x.id()==id).findFirst().orElse(null);if(id!=0&&p==null)throw new IllegalArgumentException("Elige un puesto activo del salón de esta visita.");
  StringBuilder h=new StringBuilder("<div class=\"pagehead\"><div><span class=\"eyebrow\">Evaluaciones · Nueva</span><h1>Nueva evaluación</h1><p class=\"hint\">").append(escapar(lugar)).append("</p></div><span class=\"tag\" data-modo>").append(p==null?"":p.tipo().equals("ESCRITORIO")?"Oficina":"Planta").append("</span></div><form data-evaluacion data-revision=\"si\" data-conversacion=\"si\" data-tour=\"campo\" data-fases=\"9\" action=\"/evaluaciones\" method=\"post\" enctype=\"multipart/form-data\" novalidate>").append(Html.csrf(s));
  oculto(h,"cuenta_recuerdo",""+s.cuenta().id());oculto(h,"visita",""+visita);oculto(h,"recorrido","campo");for(String n:List.of("postura","motivo","criterio","minutos","condiciones_respondidas","carga_opcion"))oculto(h,n,"");
  if(p!=null)h.append("<input type=\"hidden\" name=\"puesto\" value=\"").append(id).append("\" data-tarea=\"").append(escapar(p.descripcion())).append("\">");else{h.append("<label>Puesto de trabajo<select class=\"input\" name=\"puesto\"><option value=\"\">Elige un puesto</option>");for(var q:puestos)h.append("<option value=\"").append(q.id()).append("\" data-tarea=\"").append(escapar(q.descripcion())).append("\">").append(escapar(q.descripcion())).append("</option>");h.append("</select></label>");}
  h.append("<header class=\"campo-cabecera\"><h2 data-titulo-fijo>Bienvenida y consentimiento</h2><div class=\"row between\"><button class=\"btn\" type=\"button\" data-atras-evaluacion>← Atrás</button><span id=\"pasoActual\" role=\"status\">Paso 1 de 9</span><strong data-lado-titulo></strong></div><ol class=\"campo-progreso\" aria-label=\"Pasos de la evaluación\">");String[] nombres={"Permiso","Conversación","Condiciones","Lado","Perfil","Brazo y muñeca","Cuello y espalda","Carga","Resultado"};for(int i=0;i<9;i++)h.append("<li data-etapa=\"").append(i+1).append("\">").append(nombres[i]).append("</li>");h.append("</ol><progress max=\"9\" value=\"1\" aria-label=\"Avance de la evaluación\"></progress></header>");
  abrir(h,1,"Bienvenida y consentimiento","brazo_neutro.png",false);h.append("<p>Haz esta evaluación con el trabajador al lado. Te iremos diciendo qué mirar y qué preguntar.</p>").append(PaginasEvaluacion.opcion("acepta","si","La persona firmó en papel el consentimiento para ser evaluada y quedó archivado.","",true,"required","Las fotos son un permiso aparte."));pregunta(h,"registro","Míralo","¿Permite tomar fotos?","Confirma el permiso antes de fotografiar.",new String[][]{{"CON_FOTOS","Sí, permite fotos"},{"SIN_REGISTRO_FOTOGRAFICO","No permite fotos"}});h.append("</section>");
  abrir(h,2,"Conversación inicial","brazo_neutro.png",false);String[][] tiempos={{"MENOS_2","Menos de 2 horas"},{"DE_2_A_4","De 2 a 4 horas"},{"DE_4_A_6","Más de 4 y hasta 6"},{"DE_6_A_8","Más de 6 y hasta 8"},{"MAS_8","Más de 8 horas"}};for(var t:tiempos)t[0]=""+MapeosCampo.MINUTOS.get(t[0]);pregunta(h,"tiempo_campo","Pregúntale","¿Cuántas horas al día trabaja en este puesto?","Suma los ratos de este trabajo durante el día.",tiempos);pregunta(h,"momento_campo","Pregúntale","¿En qué momento del trabajo se siente más incómodo o más cansado?","Observa el momento que te señala.",new String[][]{{"EXIGENTE","Es el momento de mayor esfuerzo postural"},{"DURADERA","Es la postura que mantiene durante más tiempo"},{"NO_SABE","No sabe, evalúo la postura que más repite"}});h.append("<p class=\"hint\">Se guardará: <strong data-tarea-visible></strong></p></section>");
  abrir(h,3,"Condiciones del puesto","tronco_erguido.png",false);h.append("<span class=\"eyebrow\">Míralo</span><div class=\"campo-condiciones\">");for(var x:PaginasEvaluacion.CONDICIONES)h.append(PaginasEvaluacion.opcion(x[0],"si",x[1],"",true,"",x[2]));h.append(PaginasEvaluacion.opcion("ninguna","si","Ninguna","",true,"","No ves ninguna de estas condiciones.")).append("</div>").append(Formularios.texto(Map.of(),"observaciones","Otras observaciones (opcional)",255,false)).append("</section>");
  abrir(h,4,"¿Qué lado del cuerpo trabaja más?","lado_ambos.png",false);h.append("<div class=\"campo-lado\"><div>");pregunta(h,"lado_recorrido","Míralo","¿Qué lado del cuerpo trabaja más?","Si no está claro, elige Ambos.",new String[][]{{"DERECHO","Derecho"},{"IZQUIERDO","Izquierdo"},{"AMBOS","Ambos"}});h.append("</div><aside class=\"hint\"><ul><li>¿Con qué mano sostiene la herramienta, la pieza o la carga?</li><li>¿Qué brazo se levanta más o se aleja más del cuerpo?</li><li>¿Qué brazo repite más el movimiento?</li><li>¿Qué muñeca se dobla o gira más?</li></ul></aside></div></section>");
  abrir(h,5,"Foto de perfil y ángulos","brazo_neutro.png",false);h.append("<div data-subir-perfil>").append(muestra("perfil","De lado, cuerpo completo, con el brazo a la vista.")).append("<button class=\"btn p\" type=\"button\" data-perfil>Subir foto</button><input type=\"file\" hidden accept=\"image/jpeg,image/png\" data-archivo-perfil></div><div class=\"stack\" data-foto-revision hidden></div><div class=\"campo-compacta\" data-medidas-compactas hidden><p class=\"hint\">Revisa los puntos y los ángulos antes de seguir. Puedes mover los puntos con el dedo o elegir un rango.</p>");
  for(String k:List.of("BRAZO","ANTEBRAZO","CUELLO","TRONCO")){h.append("<div class=\"campo-medida\" data-medida=\"").append(k).append("\"><p><strong>").append(nombre(k)).append("</strong> <span data-angulo=\"").append(k).append("\">Sin medir</span><span class=\"tag\" data-revisar hidden>Revisar</span></p>");String[][] opciones=RecorridoCuerpo.RANGOS.get(Segmento.valueOf(k)).stream().map(r->new String[]{""+r.grados(),r.etiqueta(),r.imagen()}).toArray(String[][]::new);pregunta(h,"rango_"+k,"Míralo",preguntaAngulo(k),"Confirma lo que ves en la foto.",opciones);h.append("</div>");}h.append("<p><strong>Piernas</strong> · Las revisarás con el trabajador.</p></div></section>");
  abrir(h,6,"Brazo y muñeca","brazo_45_90.png",true);siNo(h,"hombroElevado","Míralo","¿Tiene el hombro subido?");siNo(h,"brazoSeparado","Míralo","¿Tiene el brazo separado del cuerpo?");siNo(h,"brazoApoyado","Míralo","¿Tiene el brazo apoyado en algo?");siNo(h,"antebrazoCruza","Míralo","¿El antebrazo cruza la mitad del cuerpo o sale hacia un lado?");pregunta(h,"muneca_campo","Pregúntale","¿Cómo tiene la muñeca la mayor parte del tiempo?","Mira también cómo queda la mano mientras trabaja.",new String[][]{{""+MapeosCampo.MUNECA.get("RECTA"),"Recta","muneca_neutra.png"},{""+MapeosCampo.MUNECA.get("POCO"),"Un poco doblada","muneca_15.png"},{""+MapeosCampo.MUNECA.get("MUCHO"),"Muy doblada","muneca_mas_15.png"}});siNo(h,"munecaDesviada","Pregúntale","¿Se la tuerce hacia un lado, hacia el pulgar o hacia el meñique?");pregunta(h,"giro_campo","Pregúntale","Al trabajar, ¿gira la mano hasta el límite, como al apretar un tornillo con fuerza?","Observa si llega al final del giro.",new String[][]{{"MEDIO","No, el giro es normal","giro_medio.png"},{"EXTREMO","Sí, hasta el límite","giro_extremo.png"}});h.append("<details><summary>Medir la muñeca con tres puntos (opcional)</summary><p class=\"hint\">Marca codo, muñeca y nudillos en el perfil. La foto de detalle solo es evidencia.</p><button type=\"button\" class=\"btn\" data-medir-muneca>Medir en el perfil</button></details>").append(apoyo("detalle","La mano y la muñeca de cerca. Solo sirve de evidencia.","OTRA")).append("</section>");
  abrir(h,7,"Cuello, tronco y piernas","tronco_20_60.png",true);h.append(apoyo("frente","De frente, cuerpo completo, para ver si hay giro o inclinación.","FRENTE"));siNo(h,"cuello_campo","Míralo","¿Tiene la cabeza torcida o inclinada hacia un lado?");detalle(h,"cuello_tipo","cuello_campo");siNo(h,"tronco_campo","Míralo","¿Tiene la espalda torcida o inclinada hacia un lado?");detalle(h,"tronco_tipo","tronco_campo");siNo(h,"piernas_campo","Míralo","¿Tiene los pies bien apoyados en el piso?");h.append("</section>");
  abrir(h,8,"Carga","esfuerzo_estatica.png",true);String[][] pesos={{"NADA","Nada de peso"},{"CELULAR","Menos de 2 kg (como un celular)"},{"GALON","De 2 a 10 kg (como un galón de agua)"},{"BULTO","Más de 10 kg (como un bulto)"}};pregunta(h,"peso_campo","Pregúntale","Lo más pesado que levanta o mueve en su turno, ¿se parece más a un celular, a un galón de agua o a un bulto?","Piensa en lo más pesado de esta tarea.",pesos);pregunta(h,"esfuerzo_opcion","Pregúntale","Esa postura, ¿la mantiene quieta por más de un minuto, o repite el mismo movimiento más de cuatro veces por minuto?","Puedes observar un minuto con el reloj.",new String[][]{{"NINGUNA","Ninguna, es de vez en cuando"},{"ESTATICA","La mantiene quieta"},{"REPETITIVA","La repite mucho"}});siNo(h,"golpe_campo","Pregúntale","¿La herramienta o la pieza le ha dado alguna vez un tirón o un golpe seco en la mano o en el brazo?");h.append("<p class=\"hint\" data-recuerdo-esfuerzo hidden>Del puesto anterior: revísala y pulsa Seguir para confirmarla.</p><div data-mapeos hidden>");for(String peso:List.of("NADA","CELULAR","GALON","BULTO"))for(String act:List.of("NINGUNA","ESTATICA","REPETITIVA"))for(boolean golpe:new boolean[]{false,true})h.append("<i data-peso=\"").append(peso).append("\" data-actividad=\"").append(act).append("\" data-golpe=\"").append(golpe?"si":"no").append("\" data-carga=\"").append(MapeosCampo.carga(peso,act,golpe).name()).append("\"></i>");for(String parte:List.of("cuello","tronco"))for(String tipo:List.of("GIRADA","INCLINADA","AMBAS")){var valores=MapeosCampo.orientacion("si",tipo);h.append("<i data-orientacion=\"").append(parte).append("\" data-tipo=\"").append(tipo).append("\" data-girada=\"").append(valores[0]).append("\" data-inclinada=\"").append(valores[1]).append("\"></i>");}for(var e:MapeosCampo.CRITERIOS.entrySet())h.append("<i data-momento=\"").append(e.getKey()).append("\" data-criterio=\"").append(e.getValue()).append("\"></i>");h.append("</div></section>");
  abrir(h,9,"Resultado","tronco_erguido.png",false);h.append("<div data-resultados></div><button class=\"btn\" type=\"button\" data-evaluar-otro>Evaluar también el otro lado</button></section><div class=\"aviso\" role=\"alert\" data-error-evaluacion hidden><span></span><button type=\"button\" class=\"link\" data-cerrar-error>Cerrar</button></div><div class=\"wizfoot\"><p class=\"hint\" role=\"status\" data-falta></p><button type=\"button\" class=\"btn p\" data-siguiente>Seguir →</button>").append(PaginasAnalisis.botonesGuardar()).append("</div><div data-editor-compatibilidad hidden>");String editor=PaginasAnalisis.pasos();h.append(editor.substring(0,editor.indexOf("<section class=\"card stack\" data-paso=\"6\"")).replace("data-paso=","data-editor-paso=")).append("</div></form>").append(PaginasAnalisis.scripts());return Html.pagina("Nueva evaluación",PaginasEvaluacion.fases(h.toString()),s,false,false);
 }
 private static void oculto(StringBuilder h,String n,String v){h.append("<input type=\"hidden\" name=\"").append(n).append("\" value=\"").append(escapar(v)).append("\">");}
 private static void abrir(StringBuilder h,int n,String t,String img,boolean foto){h.append("<section class=\"card stack conversacion-pantalla\" data-paso=\"").append(n).append("\"").append(n==1?"":" hidden").append("><div class=\"campo-titulo\"><h2>").append(t).append("</h2><img class=\"campo-silueta\" src=\"/static/img/tour/").append(img).append("\" alt=\"\"></div>");if(foto||n<5)h.append("<img class=\"campo-foto\" data-foto-conversacion src=\"/static/img/muestra_perfil.jpg\" alt=\"Postura de la misma evaluación\">");}
 private static void siNo(StringBuilder h,String n,String voz,String t){pregunta(h,n,voz,t,"",new String[][]{{"si","Sí"},{"no","No"}});}
 private static void detalle(StringBuilder h,String n,String depende){int inicio=h.length();pregunta(h,n,"Míralo","¿Cómo está: girada, inclinada o las dos?","Así registramos solo lo que ves, sin sumar dos cambios por uno solo.",new String[][]{{"GIRADA","Girada"},{"INCLINADA","Inclinada hacia un lado"},{"AMBAS","Las dos"}});h.insert(inicio+"<div".length()," data-cuando=\""+depende+"\"");}
 private static void pregunta(StringBuilder h,String n,String voz,String t,String ejemplo,String[][] opciones){h.append("<div class=\"campo-pregunta\" data-pregunta=\"").append(n).append("\"><span class=\"eyebrow\">").append(voz).append("</span><p id=\"pregunta-").append(n).append("\"><em>“").append(t).append("”</em></p>");if(!ejemplo.isEmpty())h.append("<small class=\"hint\">").append(ejemplo).append("</small>");h.append("<input type=\"hidden\" name=\"").append(n).append("\"><button class=\"campo-respuesta\" type=\"button\" aria-expanded=\"false\" aria-controls=\"opciones-").append(n).append("\" aria-labelledby=\"pregunta-").append(n).append(" respuesta-").append(n).append("\" data-abrir=\"").append(n).append("\"><span id=\"respuesta-").append(n).append("\">Elige una opción</span><span aria-hidden=\"true\">⌄</span></button><div class=\"campo-lista\" id=\"opciones-").append(n).append("\" hidden>");for(var x:opciones){h.append("<button type=\"button\" class=\"campo-opcion\" data-respuesta=\"").append(n).append("\" data-valor=\"").append(escapar(x[0])).append("\" aria-pressed=\"false\">");if(x.length>2)h.append("<img src=\"/static/img/tour/").append(x[2]).append("\" alt=\"\">");h.append("<span>").append(escapar(x[1])).append("</span></button>");}h.append("</div></div>");}
 private static String muestra(String tipo,String leyenda){return "<figure class=\"campo-muestra\"><img src=\"/static/img/muestra_"+tipo+".jpg\" alt=\"Ejemplo de foto de "+tipo+"\"><figcaption class=\"hint\">"+leyenda+"</figcaption></figure>";}
 private static String apoyo(String tipo,String leyenda,String vista){return "<details class=\"campo-apoyo\"><summary>Agregar foto de "+(tipo.equals("detalle")?"detalle de mano":"frente")+" (opcional)</summary>"+muestra(tipo,leyenda)+"<button type=\"button\" class=\"btn\" data-agregar=\""+vista+"\">Subir foto</button><input type=\"file\" hidden accept=\"image/jpeg,image/png\" data-archivo-extra=\""+vista+"\"><div data-apoyo-vista=\""+vista+"\"></div></details>";}
 private static String nombre(String k){return switch(k){case "ANTEBRAZO"->"Antebrazo";case "CUELLO"->"Cuello";case "TRONCO"->"Tronco";default->"Brazo";};}
 private static String preguntaAngulo(String k){return switch(k){case "ANTEBRAZO"->"¿Qué tan doblado está el codo?";case "CUELLO"->"¿Qué tan inclinada está la cabeza hacia adelante?";case "TRONCO"->"¿Qué tan inclinada está la espalda?";default->"¿Qué tan levantado está el brazo?";};}
 static String continuar(Sesion s,Evaluaciones.Consulta c){var f=c.ficha();var d=f.datos();var p=new Puesto(f.puesto(),0,null,null,f.numero(),d.postura(),"","",null,true);String html=pagina(s,List.of(p),p.id(),f.visita(),"Evaluación existente · Puesto "+f.numero());html=html.replace("action=\"/evaluaciones\"","data-criterio=\""+escapar(d.criterio())+"\" data-continuar=\""+f.id()+"\" action=\"/evaluaciones/"+f.id()+"/analisis\"");StringBuilder fotos=new StringBuilder("<div data-fotos-existentes hidden>");for(var foto:c.fotos())fotos.append("<span data-foto-id=\"").append(foto.id()).append("\" data-vista=\"").append(foto.vista()).append("\" data-descripcion=\"").append(escapar(foto.descripcion())).append("\" data-src=\"/fotos/").append(foto.id()).append("\"></span>");return html.replace("</form>",fotos.append("</div></form>").toString());}
}
